sp_widget.client_script:
api.controller = function() {

    var c = this;

    // ----------------------------------
    // INITIAL VALUES
    // ----------------------------------

    c.processing = false;

    c.rejecting = false;

    c.employeeFeedback = "";

    c.successMessage = "";

    c.errorMessage = "";


    // ==================================
    // ACCEPT HR RESOLUTION
    // ==================================

    c.acceptResolution = function() {

        c.successMessage = "";
        c.errorMessage = "";

        if (c.processing) {
            return;
        }

        c.processing = true;


        c.server.get({

            action: 'accept_resolution',

            sys_id: c.data.case.sys_id

        }).then(function(response) {

            c.processing = false;


            if (response.data.error) {

                c.errorMessage =
                    response.data.message ||
                    "Unable to confirm the resolution.";

                return;
            }


            c.data.case =
                response.data.case;


            c.successMessage =
                response.data.message ||
                "Your HR case has been resolved.";

        }, function() {

            c.processing = false;

            c.errorMessage =
                "Unable to confirm the resolution. Please try again.";

        });

    };


    // ==================================
    // SHOW REJECTION FORM
    // ==================================

    c.showRejectForm = function() {

        c.successMessage = "";
        c.errorMessage = "";

        c.rejecting = true;

    };


    // ==================================
    // CANCEL REJECTION
    // ==================================

    c.cancelReject = function() {

        c.rejecting = false;

        c.employeeFeedback = "";

        c.errorMessage = "";

    };


    // ==================================
    // REJECT HR RESOLUTION
    // ==================================

    c.rejectResolution = function() {

        c.successMessage = "";
        c.errorMessage = "";


        // Validate feedback

        if (!c.employeeFeedback ||
            !c.employeeFeedback.trim()) {

            c.errorMessage =
                "Please explain why you still need HR support.";

            return;
        }


        if (c.processing) {
            return;
        }


        c.processing = true;


        c.server.get({

            action: 'reject_resolution',

            sys_id:
                c.data.case.sys_id,

            feedback:
                c.employeeFeedback

        }).then(function(response) {

            c.processing = false;


            if (response.data.error) {

                c.errorMessage =
                    response.data.message ||
                    "Unable to send your feedback.";

                return;
            }


            c.data.case =
                response.data.case;


            c.successMessage =
                response.data.message ||
                "Your feedback has been sent to HR.";


            // Hide feedback form

            c.rejecting = false;

            c.employeeFeedback = "";


        }, function() {

            c.processing = false;

            c.errorMessage =
                "Unable to send your feedback. Please try again.";

        });

    };

};

sp_widget.css:
.ehr-page {
  max-width: 1100px;
  margin: 30px auto;
  padding: 0 20px 40px;
  color: #14213d;
}

/* HEADER */

.ehr-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 25px;
}

.ehr-header h2 {
  margin: 0 0 6px;
  font-size: 30px;
  font-weight: 700;
  color: #14213d;
}

.ehr-header p {
  margin: 0;
  color: #718096;
  font-size: 14px;
}

.ehr-back {
  color: #0066cc;
  text-decoration: none;
  font-size: 14px;
  margin-top: 8px;
}

.ehr-back:hover {
  text-decoration: underline;
}


/* SUMMARY */

.ehr-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 20px;
}

.ehr-summary-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 3px 12px rgba(0,0,0,0.05);
}

.ehr-summary-card > span {
  display: block;
  color: #718096;
  font-size: 12px;
  margin-bottom: 10px;
}

.ehr-summary-card strong {
  font-size: 15px;
  color: #14213d;
}


/* STATUS */

.status-pill {
  display: inline-block;
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
}

.status-open {
  background: #edf2f7;
  color: #4a5568;
}

.status-progress {
  background: #e8f1ff;
  color: #1d5fbf;
}

.status-awaiting {
  background: #fff4d6;
  color: #a35d00;
}

.status-resolved,
.status-closed {
  background: #dcfce7;
  color: #15803d;
}


/* GENERAL CARD */

.ehr-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 22px;
  margin-bottom: 20px;
  box-shadow: 0 3px 14px rgba(0,0,0,0.05);
}

.ehr-card-header {
  margin-bottom: 18px;
}

.ehr-card-header h3 {
  margin: 0 0 5px;
  font-size: 18px;
  font-weight: 700;
  color: #14213d;
}

.ehr-card-header p {
  margin: 0;
  color: #718096;
  font-size: 13px;
}


/* CASE INFORMATION */

.ehr-info-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 22px;
}

.ehr-field label {
  display: block;
  color: #718096;
  font-size: 12px;
  margin-bottom: 6px;
}

.ehr-field div {
  font-weight: 600;
  color: #14213d;
}

.muted-text {
  color: #94a3b8 !important;
  font-weight: 400 !important;
}


/* EMPLOYEE REQUEST */

.ehr-request-box {
  padding: 20px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  line-height: 1.7;
  color: #334155;
}


/* PROCESSING */

.ehr-processing {
  display: flex;
  align-items: center;
  gap: 18px;
}

.processing-icon {
  width: 52px;
  height: 52px;
  min-width: 52px;
  border-radius: 50%;
  background: #e8f1ff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}

.ehr-processing h3 {
  margin: 0 0 6px;
  font-size: 17px;
}

.ehr-processing p {
  margin: 0;
  color: #718096;
}


/* RESOLUTION CONFIRMATION */

.confirmation-card {
  border-left: 4px solid #0891b2;
}

.resolution-badge {
  display: inline-block;
  background: #dcfce7;
  color: #15803d;
  border-radius: 20px;
  padding: 5px 11px;
  font-size: 11px;
  font-weight: 700;
  margin-bottom: 10px;
}

.proposed-resolution {
  background: #ecfdf5;
  border: 1px solid #bbf7d0;
  border-radius: 10px;
  padding: 20px;
  margin: 18px 0;
}

.resolution-title {
  font-size: 12px;
  font-weight: 700;
  color: #15803d;
  margin-bottom: 10px;
}

.resolution-text {
  color: #334155;
  line-height: 1.7;
  white-space: pre-line;
}


/* CONFIRMATION */

.confirmation-question {
  padding-top: 18px;
  border-top: 1px solid #e2e8f0;
}

.confirmation-question h3 {
  margin: 0 0 6px;
  font-size: 18px;
}

.confirmation-question p {
  color: #718096;
  margin-bottom: 18px;
}

.confirmation-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}


/* BUTTONS */

.btn-accept,
.btn-reject,
.btn-secondary,
.btn-submit-feedback {
  border-radius: 8px;
  padding: 11px 18px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.2s;
}

.btn-accept {
  background: #16a34a;
  border: 1px solid #16a34a;
  color: white;
}

.btn-accept:hover {
  background: #15803d;
}

.btn-reject {
  background: white;
  border: 1px solid #0891b2;
  color: #087f95;
}

.btn-reject:hover {
  background: #ecfeff;
}

.btn-secondary {
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  color: #334155;
}

.btn-submit-feedback {
  background: #0891b2;
  border: 1px solid #0891b2;
  color: white;
}

.btn-submit-feedback:hover {
  background: #0e7490;
}

button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}


/* REJECTION */

.rejection-section {
  margin-top: 22px;
  padding: 20px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
}

.rejection-section h4 {
  margin: 0 0 6px;
  color: #14213d;
}

.rejection-section p {
  color: #718096;
  font-size: 13px;
}

.rejection-section textarea {
  width: 100%;
  min-height: 110px;
  padding: 12px;
  margin-top: 10px;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  resize: vertical;
  outline: none;
}

.rejection-section textarea:focus {
  border-color: #0891b2;
}

.rejection-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 14px;
}


/* RESOLVED */

.resolved-card {
  text-align: center;
  padding: 30px;
}

.resolved-icon {
  width: 58px;
  height: 58px;
  margin: 0 auto 15px;
  border-radius: 50%;
  background: #dcfce7;
  color: #15803d;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 30px;
  font-weight: bold;
}

.resolved-card h3 {
  color: #14213d;
}

.resolved-card > p {
  color: #718096;
}

.final-resolution {
  max-width: 750px;
  margin: 20px auto 0;
  text-align: left;
  background: #ecfdf5;
  border: 1px solid #bbf7d0;
  border-radius: 10px;
  padding: 18px;
}

.final-resolution p {
  margin: 8px 0 0;
  line-height: 1.7;
}


/* MESSAGES */

.ehr-message {
  border-radius: 8px;
  padding: 13px 16px;
  margin: 15px 0;
  font-size: 13px;
}

.ehr-message.success {
  background: #dcfce7;
  border: 1px solid #bbf7d0;
  color: #166534;
}

.ehr-message.error {
  background: #fee2e2;
  border: 1px solid #fecaca;
  color: #b91c1c;
}


/* RESPONSIVE */

@media (max-width: 850px) {

  .ehr-summary-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .ehr-info-grid {
    grid-template-columns: 1fr;
  }

}

@media (max-width: 550px) {

  .ehr-page {
    padding: 0 12px 30px;
  }

  .ehr-header {
    flex-direction: column;
    gap: 12px;
  }

  .ehr-summary-grid {
    grid-template-columns: 1fr;
  }

  .confirmation-actions,
  .rejection-actions {
    flex-direction: column;
  }

  .confirmation-actions button,
  .rejection-actions button {
    width: 100%;
  }

}

sp_widget.script:
(function() {

    data.caseFound = false;
    data.hasAccess = false;
    data.error = false;
    data.message = "";
    data.case = {};

    var userId = gs.getUserID();


    // ==========================================
    // GET CASE SYS_ID
    // ==========================================

    var caseSysId = "";

    if (input && input.sys_id) {
        caseSysId = input.sys_id;
    } else {
        caseSysId = $sp.getParameter('sys_id');
    }


    if (!caseSysId) {
        data.error = true;
        data.message = "No HR case was selected.";
        return;
    }


    // ==========================================
    // LOAD HR CASE
    // ==========================================

    var caseGR = new GlideRecord(
        'x_snc_unified_hr_0_hr_case'
    );

    if (!caseGR.get(caseSysId)) {

        data.error = true;
        data.message = "HR Case not found.";

        return;
    }


    data.caseFound = true;


    // ==========================================
    // EMPLOYEE ACCESS CHECK
    // Only requester can view this page
    // ==========================================

    var requestedBy =
        caseGR.getValue('request_by');

    if (requestedBy != userId) {

        data.error = true;

        data.message =
            "You are not authorized to view this HR case.";

        return;
    }


    data.hasAccess = true;


    // ==========================================
    // ACCEPT PROPOSED RESOLUTION
    // ==========================================

    if (input &&
        input.action == 'accept_resolution') {

        if (caseGR.getValue('status') !=
            'awaiting_employee_confirmation') {

            data.error = true;

            data.message =
                "This case is not waiting for employee confirmation.";

        } else {

            caseGR.setValue(
                'status',
                'resolved'
            );

            caseGR.update();

            data.message =
                "Thank you. HR Case " +
                caseGR.getDisplayValue('number') +
                " has been resolved.";

        }
    }


    // ==========================================
    // REJECT PROPOSED RESOLUTION
    // ==========================================

    if (input &&
        input.action == 'reject_resolution') {

        var feedback =
            (input.feedback || '')
                .toString()
                .trim();


        if (!feedback) {

            data.error = true;

            data.message =
                "Please explain why you still need HR support.";

        } else if (
            caseGR.getValue('status') !=
            'awaiting_employee_confirmation'
        ) {

            data.error = true;

            data.message =
                "This case is not waiting for employee confirmation.";

        } else {

            // Return case to HR
            caseGR.setValue(
                'status',
                'in_progress'
            );


            /*
             * Append employee feedback to
             * resolution notes.
             */

            var oldNotes =
                caseGR.getValue(
                    'resolution_notes'
                ) || "";


            var updatedNotes =
                oldNotes +
                "\n\nEmployee Feedback:\n" +
                feedback;


            caseGR.setValue(
                'resolution_notes',
                updatedNotes
            );


            caseGR.update();


            data.message =
                "Your feedback has been sent to HR. " +
                "The case is now back in progress.";

        }

    }


    // ==========================================
    // RELOAD LATEST RECORD
    // ==========================================

    caseGR.get(caseSysId);


    // ==========================================
    // CREATED DATE
    // ==========================================

    var createdOn =
        caseGR.getDisplayValue('created_on');

    if (!createdOn) {

        createdOn =
            caseGR.getDisplayValue(
                'sys_created_on'
            );

    }


    // ==========================================
    // PREPARE CASE DATA
    // ==========================================

    data.case = {

        sys_id:
            caseGR.getUniqueValue(),

        number:
            caseGR.getDisplayValue(
                'number'
            ),

        requested_by:
            caseGR.getDisplayValue(
                'request_by'
            ),

        category:
            caseGR.getDisplayValue(
                'category'
            ),

        assignment_group:
            caseGR.getDisplayValue(
                'assignment_group'
            ),

        assigned_to:
            caseGR.getDisplayValue(
                'assigned_to'
            ),

        status:
            caseGR.getDisplayValue(
                'status'
            ),

        status_value:
            caseGR.getValue(
                'status'
            ),

        description:
            caseGR.getDisplayValue(
                'description'
            ),

        resolution_notes:
            caseGR.getDisplayValue(
                'resolution_notes'
            ),

        created_on:
            createdOn

    };

})();
